#include <iostream>
#include <vector>

void quitar_negativos(std::vector<int>& datos) {
    for (int& valor : datos) {
        if (valor < 0) {
            valor = 0;
        }
    }
}

int main() {
    std::vector<int> datos = {-3, 5, -1};
    quitar_negativos(datos);
    for (int valor : datos) {
        std::cout << valor << "\n";
    }
    return 0;
}

#include <iostream>
#include <vector>

void limitar_altos(std::vector<int>& datos, int limite) {
    for (int& valor : datos) {
        if (valor > limite) {
            valor = limite;
        }
    }
}

int main() {
    std::vector<int> datos = {3, 9, 6};
    limitar_altos(datos, 6);
    for (int valor : datos) {
        std::cout << valor << "\n";
    }
    return 0;
}

